# ---------- trim to the planned sizes (train 300, dev +61, test 120), deterministic ----------
def _trim():
    kept_two = 0
    for g in GROUPS:
        if g["split"] == "train":
            if g["intent"] in ("specific_item", "attribute"):
                keep = 2 if kept_two < 12 and len(g["queries"]) > 1 else 1
                kept_two += keep == 2
            else:
                keep = 2
            g["queries"] = g["queries"][:keep]
    tests = [g for g in GROUPS if g["split"] == "test"]
    for g in tests[-2:]:
        g["queries"] = g["queries"][:1]


_trim()
